async def get_project_by_id(
    project_id: int = Path(...),
    db: AsyncSession = Depends(get_async_session)
) -> Project:
    project = await db.get(Project, project_id)
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    return project

@router.get("/projects/{project_id}/financials")
async def get_project_financials(
    project: Project = Depends(get_project_by_id),
    current_user: User = Depends(get_current_user)
):
    if project.organization_id != current_user.organization_id:
        raise HTTPException(status_code=403, detail="Access to project financials denied")
    return {
        "project_id": project.id,
        "total_budget": project.allocated_budget,
        "burn_rate": project.burn_rate,
        "expenses": project.total_expenses
    }
